/** Only expose the shape of an invoice number generated by the synthetic HTTP fixture. */
export function invoiceNumberDiagnostic(value: unknown): string {
  if (typeof value !== "string") return "prefix=other digits=invalid";
  const match = /^([A-Za-z]+)-([0-9]+)$/.exec(value);
  if (!match) return "prefix=other digits=invalid";
  const prefix = match[1] === "INV" || match[1] === "FAC" ? match[1] : "other";
  return `prefix=${prefix} digits=${match[2].length === 5 ? "five" : "other"}`;
}

export function invoiceStatusDiagnostic(value: unknown): string {
  if (value === 201 || value === 400 || value === 401 || value === 403 || value === 404 || value === 409 || value === 413 || value === 429) return String(value);
  if (typeof value === "number" && Number.isInteger(value) && value >= 500 && value < 600) return "5xx";
  return "other";
}

/** Three synthetic requests, with at most one status and one number each. */
export function makeInvoiceDiagnosticEmitter(write: (line: string) => void) {
  let emitted = 0;
  return (stage: unknown, kind: "status" | "number", value: unknown) => {
    if (emitted >= 6) return;
    emitted += 1;
    const safeStage = stage === "initial" || stage === "before" || stage === "after" ? stage : "other";
    const detail = kind === "number" ? invoiceNumberDiagnostic(value) : `status=${invoiceStatusDiagnostic(value)}`;
    write(`::notice title=Synthetic invoice diagnostic::${safeStage} ${detail}\n`);
  };
}
